CREATE OR REPLACE FUNCTION public.enforce_client_primary_phone() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.phone_number IS NULL OR NEW.phone_number !~ '^[0-9]{10}$' THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'رقم الهاتف مطلوب ويجب أن يكون 10 أرقام'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER require_client_primary_phone BEFORE INSERT OR UPDATE OF phone_number ON public.clients FOR EACH ROW EXECUTE FUNCTION public.enforce_client_primary_phone();
CREATE OR REPLACE FUNCTION public.enforce_policy_client_phone() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ DECLARE client_phone text; BEGIN SELECT phone_number INTO client_phone FROM public.clients WHERE id = NEW.client_id FOR SHARE; IF client_phone IS NULL OR client_phone !~ '^[0-9]{10}$' THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'لا يمكن إنشاء بوليصة بدون رقم هاتف صحيح للعميل؛ أضف رقم هاتف من 10 أرقام في حساب العميل أولاً'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER a_require_policy_client_phone BEFORE INSERT OR UPDATE OF client_id ON public.policies FOR EACH ROW EXECUTE FUNCTION public.enforce_policy_client_phone();